{"filePath":"d:\创业\睿思国际\網站\styles.css","content":":root {
  --bg: #fff9f1;
  --bg-soft: #ffe2c8;
  --ink: #13223a;
  --accent: #cf4e2f;
  --accent-2: #006a6d;
  --card: rgba(255, 255, 255, 0.78);
  --line: rgba(19, 34, 58, 0.15);
  --shadow: 0 20px 40px rgba(19, 34, 58, 0.12);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  font-family: "Manrope", "Segoe UI", sans-serif;
  color: var(--ink);
  background: radial-gradient(circle at 12% 14%, #ffd7a8 0%, transparent 32%),
    radial-gradient(circle at 88% 10%, #bce8d8 0%, transparent 30%),
    linear-gradient(165deg, var(--bg) 0%, #fff 50%, #f3fff8 100%);
  min-height: 100vh;
}

.bg-grid {
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image: linear-gradient(var(--line) 1px, transparent 1px),
    linear-gradient(90deg, var(--line) 1px, transparent 1px);
  background-size: 42px 42px;
  opacity: 0.23;
  z-index: -1;
}

.container {
  width: min(1120px, 92vw);
  margin: 0 auto;
}

.site-header {
  position: sticky;
  top: 0;
  backdrop-filter: blur(8px);
  background: rgba(255, 249, 241, 0.7);
  border-bottom: 1px solid var(--line);
  z-index: 20;
}

.nav-wrap {
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 68px;
}

.brand {
  font-family: "Noto Serif TC", serif;
  font-size: 1.2rem;
  color: var(--ink);
  text-decoration: none;
  letter-spacing: 0.08em;
}

nav {
  display: flex;
  gap: 1.2rem;
}

nav a {
  color: var(--ink);
  text-decoration: none;
  font-weight: 700;
}

.hero {
  padding: 6.8rem 0 4rem;
}

.eyebrow {
  font-weight: 800;
  color: var(--accent-2);
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

h1,
h2,
h3 {
  margin: 0;
  line-height: 1.2;
}

h1 {
  margin-top: 0.7rem;
  font-family: "Noto Serif TC", serif;
  font-size: clamp(2rem, 4vw, 3.8rem);
  max-width: 13ch;
}

.lead {
  margin-top: 1.3rem;
  font-size: 1.08rem;
  max-width: 62ch;
}

.hero-actions {
  margin-top: 1.8rem;
  display: flex;
  gap: 0.9rem;
}

.btn {
  border-radius: 999px;
  padding: 0.8rem 1.2rem;
  text-decoration: none;
  font-weight: 700;
  border: 1px solid transparent;
}

.btn-primary {
  background: var(--accent);
  color: #fff;
  box-shadow: var(--shadow);
}

.btn-ghost {
  border-color: var(--line);
  color: var(--ink);
}

.panel,
.domain-panel,
.cta {
  margin-top: 2rem;
  padding: 2rem;
  background: var(--card);
  border: 1px solid rgba(255, 255, 255, 0.7);
  box-shadow: var(--shadow);
  border-radius: 22px;
}

.cards {
  margin-top: 2rem;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
}

.card {
  background: var(--card);
  border: 1px solid rgba(255, 255, 255, 0.8);
  border-radius: 20px;
  padding: 1.4rem;
  box-shadow: var(--shadow);
}

.card p,
.panel p,
.domain-panel li,
.cta p {
  margin-top: 0.8rem;
  line-height: 1.7;
}

.domain-panel ul {
  margin: 1rem 0 0;
  padding-left: 1.2rem;
}

.site-footer {
  margin-top: 4rem;
  border-top: 1px solid var(--line);
}

.site-footer p {
  margin: 0;
  padding: 1.2rem 0 2.5rem;
}

.reveal {
  opacity: 0;
  transform: translateY(22px);
  transition: opacity 600ms ease, transform 600ms ease;
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

@media (max-width: 900px) {
  .cards {
    grid-template-columns: 1fr;
  }

  nav {
    gap: 0.7rem;
    font-size: 0.92rem;
  }

  .hero {
    padding-top: 5rem;
  }
}
"}

{"filePath":"d:\创业\睿思国际\網站\script.js","content":"const targets = document.querySelectorAll('.reveal');

const observer = new IntersectionObserver(
  (entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
        observer.unobserve(entry.target);
      }
    });
  },
  { threshold: 0.2 }
);

targets.forEach((item, index) => {
  item.style.transitionDelay = `${index * 80}ms`;
  observer.observe(item);
});
"}

