  color: var(--accent);
}

.review-list {
  margin-top: 1rem;
  display: grid;
  gap: 0.8rem;
}

.review-item {
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.75);
  border-radius: 12px;
  padding: 0.8rem;
}

.top-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.7rem;
  flex-wrap: wrap;
}

.flow-steps {
  margin-top: 1rem;
  display: grid;
  gap: 0.8rem;
}

.flow-step {
  border-left: 4px solid var(--accent-2);
  background: rgba(255, 255, 255, 0.75);
  border-radius: 10px;
  padding: 0.9rem 1rem;
}

.flow-step p {
  margin: 0.5rem 0 0;
  color: var(--muted);
}

.diagram-box {
  margin-top: 1.1rem;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 0.9rem;
  background: rgba(255, 255, 255, 0.72);
}

.diagram-box svg {
  width: 100%;
  height: auto;
}

.node {
  fill: #eff3f6;
  stroke: #6e879b;
  stroke-width: 2;
}

svg text {
  font-size: 13px;
  fill: #243642;
}

.arrow {
  stroke: #40617a;
  stroke-width: 2.2;
}

.tip {
  color: var(--muted);
}

@media (max-width: 900px) {
  .diagram-box {
    overflow-x: auto;
  }

  .diagram-box svg {
    min-width: 980px;
  }
}

const KEYS = {
  pending: 'portal_pending_users_v1',
  approved: 'portal_approved_users_v1',
  session: 'portal_session_user_v1'
};

function loadList(key) {
  const raw = localStorage.getItem(key);
  if (!raw) {
    return [];
  }
  try {
    return JSON.parse(raw);
  } catch {
    return [];
  }
}

function saveList(key, value) {
  localStorage.setItem(key, JSON.stringify(value));
}

function normalizeEmail(email) {
  return String(email || '').trim().toLowerCase();
}

function registerPage() {
  const form = document.querySelector('#register-form');
  if (!form) {
    return;
  }

  const msg = document.querySelector('#register-msg');
  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const data = new FormData(form);

    const user = {
      id: `u_${Date.now()}`,
      fullName: String(data.get('fullName') || '').trim(),
      company: String(data.get('company') || '').trim(),
      email: normalizeEmail(data.get('email')),
      phone: String(data.get('phone') || '').trim(),
      password: String(data.get('password') || ''),
      status: 'pending',
      submittedAt: new Date().toISOString()
    };

    if (!user.email || !user.password) {
      msg.textContent = '請完整填寫資料。';
      return;
    }

    const pending = loadList(KEYS.pending);
    const approved = loadList(KEYS.approved);
    const duplicated = [...pending, ...approved].some((item) => item.email === user.email);

    if (duplicated) {
      msg.textContent = '此郵箱已提交或已啟用，請直接登入或更換郵箱。';
      return;
    }

    pending.push(user);
    saveList(KEYS.pending, pending);
    form.reset();
    msg.textContent = '註冊成功，狀態為待審核。通過後即可登入查看流程頁。';
  });
}

function adminPage() {
  const panel = document.querySelector('#pending-list');
  if (!panel) {
    return;
  }

  function render() {
    const pending = loadList(KEYS.pending);
    panel.innerHTML = '';

    if (pending.length === 0) {
      panel.innerHTML = '<p>目前沒有待審核申請。</p>';
      return;
    }

    pending.forEach((user) => {
      const wrapper = document.createElement('article');
      wrapper.className = 'review-item';
      wrapper.innerHTML = `
        <p><strong>姓名：</strong>${user.fullName}</p>
        <p><strong>公司：</strong>${user.company}</p>
        <p><strong>郵箱：</strong>${user.email}</p>
        <p><strong>電話：</strong>${user.phone}</p>
      `;

      const approveBtn = document.createElement('button');
      approveBtn.className = 'btn primary';
      approveBtn.textContent = '審核通過';
      approveBtn.addEventListener('click', () => approveUser(user.id));

      const rejectBtn = document.createElement('button');
      rejectBtn.className = 'btn';
      rejectBtn.textContent = '駁回';
      rejectBtn.addEventListener('click', () => rejectUser(user.id));

      const actions = document.createElement('div');
      actions.className = 'actions';
      actions.appendChild(approveBtn);
      actions.appendChild(rejectBtn);

      wrapper.appendChild(actions);
      panel.appendChild(wrapper);
    });
  }

  function approveUser(id) {
    const pending = loadList(KEYS.pending);
    const approved = loadList(KEYS.approved);

    const target = pending.find((item) => item.id === id);
    if (!target) {
      return;
    }

    target.status = 'approved';
    target.approvedAt = new Date().toISOString();
    approved.push(target);

    saveList(
      KEYS.pending,
      pending.filter((item) => item.id !== id)
    );
    saveList(KEYS.approved, approved);
    render();
  }

  function rejectUser(id) {
    const pending = loadList(KEYS.pending);
    saveList(
      KEYS.pending,
      pending.filter((item) => item.id !== id)
    );
    render();
  }

  render();
}

function loginPage() {
  const form = document.querySelector('#login-form');
  if (!form) {
    return;
  }

  const msg = document.querySelector('#login-msg');
  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const data = new FormData(form);

    const email = normalizeEmail(data.get('email'));
    const password = String(data.get('password') || '');

    const approved = loadList(KEYS.approved);
    const matched = approved.find(
      (user) => user.email === email && user.password === password
    );

    if (!matched) {
      msg.textContent = '登入失敗：帳號未審核通過或密碼不正確。';
      return;
    }

    sessionStorage.setItem(
      KEYS.session,
      JSON.stringify({ email: matched.email, fullName: matched.fullName })
    );
    window.location.href = './agile-method.html';
  });
}

function protectedPage() {
  const logoutBtn = document.querySelector('#logout-btn');
  const isProtected = window.location.pathname.endsWith('/agile-method.html');
  if (!isProtected) {
    return;
  }

  const sessionRaw = sessionStorage.getItem(KEYS.session);
  if (!sessionRaw) {
    window.location.href = './login.html';
    return;
  }

  try {
    const sessionUser = JSON.parse(sessionRaw);
    const approved = loadList(KEYS.approved);
    const hasAccess = approved.some((user) => user.email === sessionUser.email);

    if (!hasAccess) {
      window.location.href = './login.html';
      return;
    }
  } catch {
    window.location.href = './login.html';
    return;
  }

  if (logoutBtn) {
    logoutBtn.addEventListener('click', () => {
      sessionStorage.removeItem(KEYS.session);
      window.location.href = './login.html';
    });
  }
}

registerPage();
adminPage();
loginPage();
protectedPage();

