{"filePath":"d:\创业\睿思国际\網站\secure-portal\functions\api\create-stream-direct-upload.js","content":"export async function onRequestPost(context) {
  try {
    const { request, env } = context;
    const payload = await request.json();

    if (!env.CF_ACCOUNT_ID || !env.CF_STREAM_API_TOKEN) {
      return json(
        {
          ok: false,
          error: 'Missing CF_ACCOUNT_ID or CF_STREAM_API_TOKEN environment variables.'
        },
        500
      );
    }

    const title = String(payload.title || '').trim();
    if (!title) {
      return json({ ok: false, error: 'Missing title' }, 400);
    }

    const category = String(payload.category || '').trim();

    const expiresAt = new Date(Date.now() + 1000 * 60 * 30).toISOString();

    const streamResp = await fetch(
      `https://api.cloudflare.com/client/v4/accounts/${env.CF_ACCOUNT_ID}/stream/direct_upload`,
      {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${env.CF_STREAM_API_TOKEN}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          maxDurationSeconds: 7200,
          expiry: expiresAt,
          meta: {
            title,
            category
          }
        })
      }
    );

    const data = await streamResp.json();
    if (!streamResp.ok || !data.success || !data.result?.uploadURL) {
      return json({ ok: false, error: data }, 502);
    }

    return json(
      {
        ok: true,
        uploadURL: data.result.uploadURL,
        uid: data.result.uid
      },
      200
    );
  } catch (error) {
    return json({ ok: false, error: String(error) }, 500);
  }
}

function json(payload, status) {
  return new Response(JSON.stringify(payload), {
    status,
    headers: {
      'Content-Type': 'application/json; charset=utf-8'
    }
  });
}
"}

