+function loadOrders() {
+  const raw = localStorage.getItem(KEYS.orders);
+  if (!raw) {
+    return [];
+  }
+
+  try {
+    return JSON.parse(raw);
+  } catch {
+    return [];
+  }
+}
+
+function saveOrders(orders) {
+  localStorage.setItem(KEYS.orders, JSON.stringify(orders));
+}
+
+function createOrderRecord({ customer, creator, serviceCode, orderNotes }) {
+  const service = SERVICE_CATALOG[serviceCode];
+  return {
+    id: `ord_${Date.now()}`,
+    serviceCode,
+    serviceName: service?.name || serviceCode,
+    serviceCost: service?.cost || 0,
+    orderNotes,
+    status: 'pending_confirmation',
+    customerEmail: normalizeEmail(customer.email),
+    customerName: customer.fullName,
+    customerCompany: customer.company,
+    createdByEmail: normalizeEmail(creator.email),
+    createdByName: creator.fullName,
+    createdAt: new Date().toISOString()
+  };
+}
+
+function storeOrder(order) {
+  const orders = loadOrders();
+  orders.unshift(order);
+  saveOrders(orders);
+  return order;
+}
+
+function updateOrder(orderId, updater) {
+  const orders = loadOrders();
+  const nextOrders = orders.map((order) => {
+    if (order.id !== orderId) {
+      return order;
+    }
+
+    return updater(order);
+  });
+  saveOrders(nextOrders);
+  return nextOrders.find((order) => order.id === orderId) || null;
+}
+
+function getOrdersForUser(email, includeAll) {
+  const normalizedEmail = normalizeEmail(email);
+  const orders = loadOrders();
+  if (includeAll) {
+    return orders;
+  }
+
+  return orders.filter((order) => order.customerEmail === normalizedEmail);
+}
+
