+      `<p><strong>備註：</strong>${order.orderNotes}</p>`,
+      `<p><strong>建單人：</strong>${order.createdByName}</p>`
+    ];
+
+    if (order.confirmedAt) {
+      metaLines.push(`<p><strong>確認時間：</strong>${new Date(order.confirmedAt).toLocaleString('zh-Hant')}</p>`);
+    }
+
+    item.innerHTML = `
