+      confirmBtn.type = 'button';
+      confirmBtn.textContent = `確認服務並扣除 ${order.serviceCost} 積分`;
+      confirmBtn.addEventListener('click', () => onConfirm(order));
+      actions.appendChild(confirmBtn);
+      item.appendChild(actions);
+    }
+
